using System;
using System.Collections.Generic;
using Framework.AI.Core;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 敵AIの認識制御システムを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyPerceptionControllerTest
        : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("テスト用ステージ管理Prefab。")]
        private MazeStageManager stageManagerPrefab;

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 48;

        /// <summary>
        /// 敵AIの初期座標。
        /// </summary>
        private static readonly Vector2Int Origin =
            new Vector2Int(1, 1);

        /// <summary>
        /// テスト用プレイヤーの識別子。
        /// </summary>
        private readonly Guid playerId = Guid.NewGuid();

        /// <summary>
        /// テスト用脅威対象の識別子。
        /// </summary>
        private readonly Guid threatId = Guid.NewGuid();

        /// <summary>
        /// テスト用ステージ管理インスタンス。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用移動コントローラー。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用パラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト用敵AIコンテキスト。
        /// </summary>
        private MazeEnemyContext context;

        /// <summary>
        /// テスト対象の認識制御システム。
        /// </summary>
        private MazeEnemyPerceptionController controller;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Prepare();
                TestInitialization();

                Prepare();
                TestVisibility();

                Prepare();
                TestMemory();

                Prepare();
                TestMultipleTargets();

                Prepare();
                TestEvents();

                Prepare();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemyPerceptionController テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト環境を初期化する。
        /// </summary>
        private void Prepare()
        {
            Cleanup();

            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用ステージPrefabが未設定です。");
            }

            stageManager = Instantiate(stageManagerPrefab);

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "ステージ生成に失敗しました。");
            }

            if (stageManager.Map.Width < 10 ||
                stageManager.Map.Height < 5)
            {
                throw new InvalidOperationException(
                    "テスト用グリッドは10×5以上が必要です。");
            }

            // 視認判定を固定条件で検証する。
            stageManager.Map.Fill(MazeCell.CreateFloor());

            // ステージ開始直後のクリアを防止する。
            stageManager.Map.SetCell(
                new Vector2Int(0, 0),
                MazeCell.CreateFloor(MazeCellFlags.Gem));

            movementObject =
                new GameObject("PerceptionTest_Movement");

            movement = movementObject
                .AddComponent<GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                Origin);

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            parameters.SetBaseValue(
                MazeEnemyParameter.DetectionRange,
                4f);

            parameters.SetBaseValue(
                MazeEnemyParameter.ThreatDetectionRange,
                7f);

            parameters.SetBaseValue(
                MazeEnemyParameter.MemoryDuration,
                5f);

            var agentContext =
                new AgentContext<MazeEnemyParameter>(
                    "PerceptionTest",
                    parameters);

            context = new MazeEnemyContext(
                agentContext,
                stageManager,
                movement,
                Origin);

            controller =
                new MazeEnemyPerceptionController(context);

            if (!stageManager.StartStage() ||
                !context.CanAct)
            {
                throw new InvalidOperationException(
                    "テスト用ステージを開始できません。");
            }
        }

        /// <summary>
        /// テスト用プレイヤー情報を生成する。
        /// </summary>
        /// <param name="position">プレイヤーの座標</param>
        /// <param name="direction">移動方向</param>
        /// <param name="isActive">有効状態</param>
        /// <returns>プレイヤーの現在情報</returns>
        private MazeEnemyTargetSnapshot CreatePlayer(
            Vector2Int position,
            Vector2Int direction = default,
            bool isActive = true)
        {
            return new MazeEnemyTargetSnapshot(
                playerId,
                MazeEnemyTargetType.Player,
                position,
                direction,
                4f,
                isActive);
        }

        /// <summary>
        /// テスト用脅威対象情報を生成する。
        /// </summary>
        /// <param name="position">脅威対象の座標</param>
        /// <returns>脅威対象の現在情報</returns>
        private MazeEnemyTargetSnapshot CreateThreat(
            Vector2Int position)
        {
            return new MazeEnemyTargetSnapshot(
                threatId,
                MazeEnemyTargetType.Threat,
                position,
                Vector2Int.left,
                5f);
        }

        /// <summary>
        /// 指定対象を使用して認識情報を更新する。
        /// </summary>
        /// <param name="targets">認識対象一覧</param>
        private void UpdateTargets(
            params MazeEnemyTargetSnapshot[] targets)
        {
            if (!controller.UpdatePerception(targets))
            {
                throw new InvalidOperationException(
                    "認識情報の更新に失敗しました。");
            }
        }

        /// <summary>
        /// 初期状態と入力情報の検証を行う。
        /// </summary>
        private void TestInitialization()
        {
            bool contextPassed =
                ReferenceEquals(
                    controller.Context,
                    context);

            Debug.Assert(contextPassed, "コンテキスト参照", this);
            Check(contextPassed, "コンテキスト参照");

            bool validPassed =
                controller.IsValid &&
                !controller.IsDisposed;

            Debug.Assert(validPassed, "初期有効状態", this);
            Check(validPassed, "初期有効状態");

            bool countPassed =
                controller.Count == 0 &&
                controller.VisibleCount == 0 &&
                controller.RememberedCount == 0;

            Debug.Assert(countPassed, "初期認識件数", this);
            Check(countPassed, "初期認識件数");

            bool unknownPassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Unknown &&
                !controller.TryGetObservation(
                    playerId,
                    out var unknown) &&
                !unknown.IsValid;

            Debug.Assert(unknownPassed, "未認識対象の取得", this);
            Check(unknownPassed, "未認識対象の取得");

            bool nullPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new MazeEnemyPerceptionController(null);
                });

            Debug.Assert(nullPassed, "nullコンテキストの拒否", this);
            Check(nullPassed, "nullコンテキストの拒否");

            bool snapshotPassed =
                CreatePlayer(Origin).IsValid &&
                !default(MazeEnemyTargetSnapshot).IsValid;

            Debug.Assert(snapshotPassed, "対象情報の有効判定", this);
            Check(snapshotPassed, "対象情報の有効判定");

            bool idPassed =
                Throws<ArgumentException>(() =>
                {
                    new MazeEnemyTargetSnapshot(
                        Guid.Empty,
                        MazeEnemyTargetType.Player,
                        Origin,
                        Vector2Int.zero,
                        1f);
                });

            Debug.Assert(idPassed, "無効な識別子の拒否", this);
            Check(idPassed, "無効な識別子の拒否");

            bool invalidInputPassed =
                Throws<ArgumentException>(() =>
                {
                    new MazeEnemyTargetSnapshot(
                        playerId,
                        MazeEnemyTargetType.None,
                        Origin,
                        Vector2Int.zero,
                        1f);
                }) &&
                Throws<ArgumentException>(() =>
                {
                    new MazeEnemyTargetSnapshot(
                        playerId,
                        MazeEnemyTargetType.Player,
                        Origin,
                        Vector2Int.one,
                        1f);
                }) &&
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new MazeEnemyTargetSnapshot(
                        playerId,
                        MazeEnemyTargetType.Player,
                        Origin,
                        Vector2Int.zero,
                        -1f);
                });

            Debug.Assert(invalidInputPassed, "無効な対象情報の拒否", this);
            Check(invalidInputPassed, "無効な対象情報の拒否");
        }

        /// <summary>
        /// 視認距離と遮蔽物の判定を検証する。
        /// </summary>
        private void TestVisibility()
        {
            UpdateTargets(
                CreatePlayer(
                    new Vector2Int(3, 1),
                    Vector2Int.right));

            bool detectedPassed =
                controller.TryGetObservation(
                    playerId,
                    out var detected) &&
                detected.IsVisible &&
                detected.Confidence == 1f;

            Debug.Assert(detectedPassed, "プレイヤーの視認", this);
            Check(detectedPassed, "プレイヤーの視認");

            bool informationPassed =
                detected.LastKnownPosition ==
                    new Vector2Int(3, 1) &&
                detected.LastKnownDirection ==
                    Vector2Int.right &&
                detected.LastKnownMoveSpeed == 4f;

            Debug.Assert(informationPassed, "観測情報の反映", this);
            Check(informationPassed, "観測情報の反映");

            UpdateTargets(
                CreatePlayer(new Vector2Int(5, 1)));

            bool boundaryPassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Visible;

            Debug.Assert(boundaryPassed, "認識距離境界の視認", this);
            Check(boundaryPassed, "認識距離境界の視認");

            UpdateTargets(
                CreatePlayer(new Vector2Int(6, 1)));

            bool rangePassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Remembered;

            Debug.Assert(rangePassed, "認識距離外の判定", this);
            Check(rangePassed, "認識距離外の判定");

            UpdateTargets(
                CreateThreat(new Vector2Int(7, 1)));

            bool threatPassed =
                controller.GetState(threatId) ==
                    MazeEnemyTargetState.Visible;

            Debug.Assert(threatPassed, "脅威専用認識距離", this);
            Check(threatPassed, "脅威専用認識距離");

            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateWall());

            controller.Clear();

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            bool wallPassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Unknown;

            Debug.Assert(wallPassed, "壁による視線遮断", this);
            Check(wallPassed, "壁による視線遮断");

            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateFloor());

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            bool recoveryPassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Visible;

            Debug.Assert(recoveryPassed, "遮蔽物除去後の視認", this);
            Check(recoveryPassed, "遮蔽物除去後の視認");

            controller.Clear();

            UpdateTargets(
                CreatePlayer(
                    new Vector2Int(3, 1),
                    isActive: false),
                CreateThreat(new Vector2Int(-1, 1)));

            bool inactivePassed =
                controller.Count == 0;

            Debug.Assert(inactivePassed, "無効対象と範囲外対象の除外", this);
            Check(inactivePassed, "無効対象と範囲外対象の除外");
        }

        /// <summary>
        /// 観測情報の記憶と再発見を検証する。
        /// </summary>
        private void TestMemory()
        {
            UpdateTargets(
                CreatePlayer(
                    new Vector2Int(3, 1),
                    Vector2Int.right));

            bool memoryPassed =
                context.TryRecallObservation(
                    playerId,
                    out var stimulus,
                    out float confidence) &&
                stimulus.Position ==
                    new Vector2Int(3, 1) &&
                confidence == 1f;

            Debug.Assert(memoryPassed, "認識記憶への保存", this);
            Check(memoryPassed, "認識記憶への保存");

            UpdateTargets(
                CreatePlayer(
                    new Vector2Int(8, 1),
                    Vector2Int.up));

            bool rememberedPassed =
                controller.TryGetObservation(
                    playerId,
                    out var remembered) &&
                remembered.IsRemembered &&
                controller.VisibleCount == 0 &&
                controller.RememberedCount == 1;

            Debug.Assert(rememberedPassed, "見失った対象の記憶", this);
            Check(rememberedPassed, "見失った対象の記憶");

            bool positionPassed =
                remembered.LastKnownPosition ==
                    new Vector2Int(3, 1);

            Debug.Assert(positionPassed, "最後の観測座標の維持", this);
            Check(positionPassed, "最後の観測座標の維持");

            bool directionPassed =
                remembered.LastKnownDirection ==
                    Vector2Int.right;

            Debug.Assert(directionPassed, "未視認方向の漏洩防止", this);
            Check(directionPassed, "未視認方向の漏洩防止");

            UpdateTargets();

            bool absentPassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Remembered;

            Debug.Assert(absentPassed, "一覧から消えた対象の記憶維持", this);
            Check(absentPassed, "一覧から消えた対象の記憶維持");

            UpdateTargets(
                CreatePlayer(
                    new Vector2Int(2, 1),
                    Vector2Int.left));

            bool rediscoveredPassed =
                controller.TryGetObservation(
                    playerId,
                    out var rediscovered) &&
                rediscovered.IsVisible &&
                rediscovered.LastKnownPosition ==
                    new Vector2Int(2, 1) &&
                rediscovered.LastKnownDirection ==
                    Vector2Int.left;

            Debug.Assert(rediscoveredPassed, "再発見時の情報更新", this);
            Check(rediscoveredPassed, "再発見時の情報更新");

            parameters.SetBaseValue(
                MazeEnemyParameter.MemoryDuration,
                0f);

            UpdateTargets(
                CreatePlayer(new Vector2Int(2, 1)));

            bool disabledVisiblePassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Visible &&
                !context.TryRecallObservation(
                    playerId,
                    out _,
                    out _);

            Debug.Assert(disabledVisiblePassed, "記憶無効時の視認維持", this);
            Check(disabledVisiblePassed, "記憶無効時の視認維持");

            UpdateTargets();

            bool disabledLostPassed =
                controller.Count == 0 &&
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Unknown;

            Debug.Assert(disabledLostPassed, "記憶無効時の即時消失", this);
            Check(disabledLostPassed, "記憶無効時の即時消失");
        }

        /// <summary>
        /// 複数対象と優先対象の選定を検証する。
        /// </summary>
        private void TestMultipleTargets()
        {
            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)),
                CreateThreat(new Vector2Int(6, 1)));

            bool multiplePassed =
                controller.Count == 2 &&
                controller.VisibleCount == 2;

            Debug.Assert(multiplePassed, "複数対象の同時認識", this);
            Check(multiplePassed, "複数対象の同時認識");

            bool playerPassed =
                controller.TryGetBestObservation(
                    MazeEnemyTargetType.Player,
                    out var player) &&
                player.Id == playerId;

            Debug.Assert(playerPassed, "プレイヤー種類別取得", this);
            Check(playerPassed, "プレイヤー種類別取得");

            bool threatPassed =
                controller.TryGetBestObservation(
                    MazeEnemyTargetType.Threat,
                    out var threat) &&
                threat.Id == threatId;

            Debug.Assert(threatPassed, "脅威種類別取得", this);
            Check(threatPassed, "脅威種類別取得");

            Guid secondPlayerId = Guid.NewGuid();

            var secondPlayer =
                new MazeEnemyTargetSnapshot(
                    secondPlayerId,
                    MazeEnemyTargetType.Player,
                    new Vector2Int(2, 1),
                    Vector2Int.zero,
                    4f);

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)),
                secondPlayer,
                CreateThreat(new Vector2Int(6, 1)));

            bool nearestPassed =
                controller.TryGetBestObservation(
                    MazeEnemyTargetType.Player,
                    out var nearest) &&
                nearest.Id == secondPlayerId;

            Debug.Assert(nearestPassed, "近い対象の優先選定", this);
            Check(nearestPassed, "近い対象の優先選定");

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            bool visiblePriorityPassed =
                controller.TryGetBestObservation(
                    MazeEnemyTargetType.Player,
                    out var visible) &&
                visible.Id == playerId &&
                visible.IsVisible;

            Debug.Assert(visiblePriorityPassed, "視認対象の優先選定", this);
            Check(visiblePriorityPassed, "視認対象の優先選定");

            var results =
                new List<MazeEnemyTargetObservation>();

            bool listPassed =
                controller.GetObservations(results) == 3 &&
                results.Count == 3 &&
                controller.VisibleCount == 1 &&
                controller.RememberedCount == 2;

            Debug.Assert(listPassed, "観測情報一覧の取得", this);
            Check(listPassed, "観測情報一覧の取得");

            UpdateTargets(
                CreatePlayer(new Vector2Int(2, 1)),
                CreatePlayer(new Vector2Int(4, 1)));

            bool duplicatePassed =
                controller.TryGetObservation(
                    playerId,
                    out var duplicate) &&
                duplicate.LastKnownPosition ==
                    new Vector2Int(2, 1) &&
                controller.Count == 3;

            Debug.Assert(duplicatePassed, "重複識別子の処理", this);
            Check(duplicatePassed, "重複識別子の処理");

            controller.Clear();

            bool emptyPassed =
                controller.GetObservations(results) == 0 &&
                results.Count == 0 &&
                !controller.TryGetBestObservation(
                    MazeEnemyTargetType.Player,
                    out var empty) &&
                !empty.IsValid;

            Debug.Assert(emptyPassed, "空の観測情報一覧", this);
            Check(emptyPassed, "空の観測情報一覧");
        }

        /// <summary>
        /// 認識イベントと状態遷移を検証する。
        /// </summary>
        private void TestEvents()
        {
            int detectedCount = 0;
            int lostCount = 0;
            int forgottenCount = 0;
            int stateChangedCount = 0;

            bool callbackStateValid = true;
            bool reentryRejected = false;

            controller.TargetDetected += observation =>
            {
                detectedCount++;

                callbackStateValid &=
                    controller.GetState(observation.Id) ==
                        MazeEnemyTargetState.Visible;

                reentryRejected =
                    !controller.Forget(observation.Id);
            };

            controller.TargetLost += observation =>
            {
                lostCount++;
            };

            controller.TargetForgotten += id =>
            {
                forgottenCount++;

                callbackStateValid &=
                    controller.GetState(id) ==
                        MazeEnemyTargetState.Unknown;
            };

            controller.TargetStateChanged +=
                (id, previous, next) =>
                {
                    stateChangedCount++;

                    callbackStateValid &=
                        controller.GetState(id) == next;
                };

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            bool detectionPassed =
                detectedCount == 1 &&
                stateChangedCount == 1;

            Debug.Assert(detectionPassed, "発見イベント", this);
            Check(detectionPassed, "発見イベント");

            UpdateTargets(
                CreatePlayer(new Vector2Int(2, 1)));

            bool repeatedPassed =
                detectedCount == 1 &&
                stateChangedCount == 1;

            Debug.Assert(repeatedPassed, "視認継続時の重複通知抑制", this);
            Check(repeatedPassed, "視認継続時の重複通知抑制");

            UpdateTargets();

            bool lostPassed =
                lostCount == 1 &&
                stateChangedCount == 2;

            Debug.Assert(lostPassed, "視認喪失イベント", this);
            Check(lostPassed, "視認喪失イベント");

            UpdateTargets();

            bool repeatedLostPassed =
                lostCount == 1 &&
                stateChangedCount == 2;

            Debug.Assert(repeatedLostPassed, "記憶継続時の重複通知抑制", this);
            Check(repeatedLostPassed, "記憶継続時の重複通知抑制");

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            bool rediscoveredPassed =
                detectedCount == 2 &&
                stateChangedCount == 3;

            Debug.Assert(rediscoveredPassed, "再発見イベント", this);
            Check(rediscoveredPassed, "再発見イベント");

            bool forgottenPassed =
                controller.Forget(playerId) &&
                forgottenCount == 1 &&
                stateChangedCount == 4 &&
                !controller.Forget(playerId);

            Debug.Assert(forgottenPassed, "記憶削除イベント", this);
            Check(forgottenPassed, "記憶削除イベント");

            Debug.Assert(callbackStateValid, "イベント通知時の状態整合性", this);
            Check(callbackStateValid, "イベント通知時の状態整合性");

            Debug.Assert(reentryRejected, "イベント内の再入変更拒否", this);
            Check(reentryRejected, "イベント内の再入変更拒否");
        }

        /// <summary>
        /// 停止状態と破棄処理を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            bool nullPassed =
                !controller.UpdatePerception(null) &&
                Throws<ArgumentNullException>(() =>
                {
                    controller.GetObservations(null);
                });

            Debug.Assert(nullPassed, "null入力への対応", this);
            Check(nullPassed, "null入力への対応");

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            stageManager.PauseStage();

            bool pausePassed =
                !controller.UpdatePerception(
                    Array.Empty<MazeEnemyTargetSnapshot>()) &&
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Visible;

            Debug.Assert(pausePassed, "停止中の認識更新抑制", this);
            Check(pausePassed, "停止中の認識更新抑制");

            stageManager.ResumeStage();

            UpdateTargets();

            bool resumePassed =
                controller.GetState(playerId) ==
                    MazeEnemyTargetState.Remembered;

            Debug.Assert(resumePassed, "再開後の認識更新", this);
            Check(resumePassed, "再開後の認識更新");

            bool forgetPassed =
                controller.Forget(playerId) &&
                !context.TryRecallObservation(
                    playerId,
                    out _,
                    out _);

            Debug.Assert(forgetPassed, "認識記憶との連動削除", this);
            Check(forgetPassed, "認識記憶との連動削除");

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)),
                CreateThreat(new Vector2Int(6, 1)));

            bool clearPassed =
                controller.Clear() &&
                controller.Count == 0 &&
                controller.VisibleCount == 0 &&
                context.PerceptionMemory.Count == 0;

            Debug.Assert(clearPassed, "全認識情報の削除", this);
            Check(clearPassed, "全認識情報の削除");

            UpdateTargets(
                CreatePlayer(new Vector2Int(3, 1)));

            controller.Dispose();
            controller.Dispose();

            bool disposedPassed =
                controller.IsDisposed &&
                !controller.IsValid &&
                controller.Count == 0 &&
                context.PerceptionMemory.Count == 0;

            Debug.Assert(disposedPassed, "重複破棄と記憶解放", this);
            Check(disposedPassed, "重複破棄と記憶解放");

            bool ownershipPassed =
                context.IsValid &&
                !parameters.IsDisposed &&
                !controller.Clear() &&
                !controller.Forget(playerId) &&
                !controller.UpdatePerception(
                    Array.Empty<MazeEnemyTargetSnapshot>());

            Debug.Assert(ownershipPassed, "外部所有権維持と破棄後の変更拒否", this);
            Check(ownershipPassed, "外部所有権維持と破棄後の変更拒否");

            controller =
                new MazeEnemyPerceptionController(context);

            context.Dispose();

            bool dependencyPassed =
                !controller.IsValid &&
                !controller.TryGetObservation(
                    playerId,
                    out _) &&
                !controller.UpdatePerception(
                    Array.Empty<MazeEnemyTargetSnapshot>());

            Debug.Assert(dependencyPassed, "依存コンテキスト破棄への対応", this);
            Check(dependencyPassed, "依存コンテキスト破棄への対応");
        }

        /// <summary>
        /// 指定された型の例外が発生するか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">実行する処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();

                return false;
            }
            catch (Exception exception)
            {
                return exception.GetType() ==
                    typeof(TException);
            }
        }

        /// <summary>
        /// テスト環境を破棄する。
        /// </summary>
        private void Cleanup()
        {
            controller?.Dispose();
            controller = null;

            context?.Dispose();
            context = null;

            parameters?.Dispose();
            parameters = null;

            if (movementObject != null)
            {
                movementObject.SetActive(false);
                Destroy(movementObject);

                movementObject = null;
            }

            movement = null;

            if (stageManager != null)
            {
                stageManager.gameObject.SetActive(false);
                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// オブジェクト破棄時にテスト環境を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Cleanup();
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
